mapper.select:
SELECT st.*, e.name AS exam_name, es.subject_name FROM score_statistics st LEFT JOIN exam e ON e.id = st.exam_id LEFT JOIN exam_subject es ON es.id = st.exam_subject_id WHERE st.exam_id = #{examId}
AND st.exam_subject_id = #{examSubjectId} AND st.stat_type = 3
AND st.exam_subject_id IS NULL AND st.stat_type = 4
